 	if !ok {
 		t.Fatalf("missing class-field arrow method %q in %#v", "Service.create", entities)
 	}
 	if want := "create = (name: string) =>"; create.Signature != want {
 		t.Fatalf("class-field arrow signature = %q, want %q", create.Signature, want)
 	}
